return [{ json: { _ok: true, active_only } }];

const h = $json.headers || {};
const token = h['x-symbalyx-token'] || h['X-Symbalyx-Token'] || '';
const expected = $env.SYMBALYX_WEBHOOK_SECRET || '';
if (!expected) return [{ json: { _ok: false, _status: 500, _error: 'SYMBALYX_WEBHOOK_SECRET not configured' } }];
if (token !== expected) return [{ json: { _ok: false, _status: 401, _error: 'invalid_token' } }];
const b = $json.body || {};
const name = String(b.name || '').trim();
const email = String(b.email || '').trim();
const role = String(b.role || 'member').trim().toLowerCase();
const initials = String(b.initials || '').trim().toUpperCase().slice(0, 4);
const color = String(b.color || '').trim();
const ALLOWED_ROLES = ['founder','admin','sales','dev','viewer','member'];
if (!name) return [{ json: { _ok: false, _status: 400, _error: 'missing name' } }];
if (name.length > 80) return [{ json: { _ok: false, _status: 400, _error: 'name too long' } }];
if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return [{ json: { _ok: false, _status: 400, _error: 'invalid email' } }];
if (!ALLOWED_ROLES.includes(role)) return [{ json: { _ok: false, _status: 400, _error: 'invalid role (allowed: '+ALLOWED_ROLES.join(',')+')' } }];
if (color && !/^#[0-9a-fA-F]{3,8}$/.test(color)) return [{ json: { _ok: false, _status: 400, _error: 'invalid color (hex expected)' } }];
const auto_initials = initials || name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase().slice(0,4);
const id = 'tm_' + Date.now().toString(36) + Math.random().toString(36).slice(2,5);
return [{ json: { _ok: true, id, name, email, role, initials: auto_initials, color: color || '#3a86ff', is_active: true, created_at: new Date().toISOString() } }];

const h = $json.headers || {};
const token = h['x-symbalyx-token'] || h['X-Symbalyx-Token'] || '';
const expected = $env.SYMBALYX_WEBHOOK_SECRET || '';
if (!expected) return [{ json: { _ok: false, _status: 500, _error: 'SYMBALYX_WEBHOOK_SECRET not configured' } }];
if (token !== expected) return [{ json: { _ok: false, _status: 401, _error: 'invalid_token' } }];
const b = $json.body || {};
const id = String(b.id || '').trim();
if (!id) return [{ json: { _ok: false, _status: 400, _error: 'missing id' } }];
const patch = {};
if (b.is_active !== undefined) patch.is_active = (b.is_active === true || String(b.is_active).toLowerCase() === 'true');
if (b.role !== undefined) {
  const ALLOWED_ROLES = ['founder','admin','sales','dev','viewer','member'];
  const role = String(b.role).trim().toLowerCase();
  if (!ALLOWED_ROLES.includes(role)) return [{ json: { _ok: false, _status: 400, _error: 'invalid role' } }];
  patch.role = role;
}
if (b.name !== undefined) patch.name = String(b.name).trim().slice(0,80);
if (b.email !== undefined) {
  const e = String(b.email).trim();
  if (e && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)) return [{ json: { _ok: false, _status: 400, _error: 'invalid email' } }];
  patch.email = e;
}
if (b.initials !== undefined) patch.initials = String(b.initials).trim().toUpperCase().slice(0,4);
if (b.color !== undefined) {
  const c = String(b.color).trim();
  if (c && !/^#[0-9a-fA-F]{3,8}$/.test(c)) return [{ json: { _ok: false, _status: 400, _error: 'invalid color' } }];
  patch.color = c;
}
if (Object.keys(patch).length === 0) return [{ json: { _ok: false, _status: 400, _error: 'no fields to update' } }];
return [{ json: { _ok: true, id, patch } }];

const inp = $('Auth GET').first().json;
const all = items.map(i => i.json);
const toBool = v => v === true || String(v).toLowerCase() === 'true' || String(v) === '1';
const filtered = inp.active_only ? all.filter(m => toBool(m.is_active)) : all;
filtered.sort((a,b) => String(a.name||'').localeCompare(String(b.name||'')));
// Normalisation booléennes pour le client.
const out = filtered.map(m => ({ ...m, is_active: toBool(m.is_active) }));
return [{ json: { ok: true, count: out.length, members: out } }];

// Merge patch + ligne existante. Sans ça, defineBelow + expressions sur des champs
// absents écrirait '' dans Sheets et effacerait les colonnes.
const inp = $('Auth & build PATCH').first().json;
const rows = items.map(i => i.json);
const row = rows.find(r => String(r.id) === String(inp.id));
if (!row) {
  return [{ json: { _ok: false, _status: 404, _error: 'team_member not found: ' + inp.id } }];
}
const toBool = v => v === true || String(v).toLowerCase() === 'true' || String(v) === '1';
const merged = {
  id: row.id,
  name: inp.patch.name !== undefined ? inp.patch.name : (row.name || ''),
  email: inp.patch.email !== undefined ? inp.patch.email : (row.email || ''),
  role: inp.patch.role !== undefined ? inp.patch.role : (row.role || 'member'),
  initials: inp.patch.initials !== undefined ? inp.patch.initials : (row.initials || ''),
  color: inp.patch.color !== undefined ? inp.patch.color : (row.color || ''),
  is_active: inp.patch.is_active !== undefined ? !!inp.patch.is_active : toBool(row.is_active),
  created_at: row.created_at || ''
};
return [{ json: merged }];
